
(function(){
  window.KFM_PLAYER='data:image/webp;base64,';

  function fr(a){ try{ return (window.UT_FRAMES||{})[a]||''; }catch(e){ return ''; } }
  function pk(k){ try{ return (typeof packByKey==='function'?packByKey(k):null); }catch(e){ return null; } }
  function nfmt(n){ try{ return (typeof fmt==='function')?fmt(n):String(n); }catch(e){ return String(n); } }
  function ee(s){ try{ return (typeof esc2==='function')?esc2(s):String(s); }catch(e){ return String(s); } }

  var COIN='<svg viewBox="0 0 64 64">'+
    '<defs><linearGradient id="kcA" x1="0" y1="0" x2="0" y2="1">'+
      '<stop offset="0" stop-color="#ffeeb0"/><stop offset=".48" stop-color="#f6c63f"/>'+
      '<stop offset="1" stop-color="#b47a12"/></linearGradient>'+
    '<linearGradient id="kcB" x1="0" y1="0" x2="1" y2="1">'+
      '<stop offset="0" stop-color="#fff6d4"/><stop offset=".5" stop-color="#f7cd54"/>'+
      '<stop offset="1" stop-color="#c98d17"/></linearGradient></defs>'+
    '<ellipse cx="26" cy="52" rx="20" ry="7.4" fill="#8d600d"/>'+
    '<ellipse cx="26" cy="49" rx="20" ry="7.4" fill="url(#kcA)"/>'+
    '<ellipse cx="26" cy="45.4" rx="20" ry="7.4" fill="#8d600d"/>'+
    '<ellipse cx="26" cy="42.6" rx="20" ry="7.4" fill="url(#kcA)"/>'+
    '<ellipse cx="26" cy="39" rx="20" ry="7.4" fill="#8d600d"/>'+
    '<ellipse cx="26" cy="36.2" rx="20" ry="7.4" fill="url(#kcA)"/>'+
    '<circle cx="42" cy="25" r="18" fill="#8d600d"/>'+
    '<circle cx="42" cy="23" r="18" fill="url(#kcB)"/>'+
    '<circle cx="42" cy="23" r="13.4" fill="none" stroke="#a97313" stroke-width="1.6" opacity=".75"/>'+
    '<path d="M47.6 16.6a8.6 8.6 0 1 0 0 12.8M35.6 20.6h9M35.6 25h9" fill="none" stroke="#8a5f10" '+
      'stroke-width="2.6" stroke-linecap="round"/></svg>';

  var EXPIC='<svg viewBox="0 0 64 64">'+
    '<defs><linearGradient id="kxA" x1="0" y1="0" x2="0" y2="1">'+
      '<stop offset="0" stop-color="#bff1ff"/><stop offset=".5" stop-color="#43b6f0"/>'+
      '<stop offset="1" stop-color="#1a6bb5"/></linearGradient></defs>'+
    '<path d="M32 3.6 56 17v30L32 60.4 8 47V17z" fill="url(#kxA)" stroke="#d6f4ff" stroke-width="2.2" '+
      'stroke-linejoin="round"/>'+
    '<path d="M32 3.6 56 17 32 30.4 8 17z" fill="#ffffff" opacity=".18"/>'+
    '<path d="M23 40V27l9-9 9 9v13" fill="none" stroke="#eafbff" stroke-width="3.4" stroke-linecap="round" '+
      'stroke-linejoin="round"/>'+
    '<path d="M32 45V19" fill="none" stroke="#eafbff" stroke-width="3.4" stroke-linecap="round"/></svg>';

  window.rwArt=function(rw){
    try{
      if(!rw) return '';
      if(rw.t==='pack'){
        var p=pk(rw.v)||{art:'bronze'};
        return '<span class="rw-art"><span class="rw-pk" style="background-image:url('+fr(p.art)+')"></span></span>';
      }
      if(rw.t==='exp')
        return '<span class="rw-art"><span class="rw-ic exp">'+EXPIC+'</span></span>';
      return '<span class="rw-art"><span class="rw-ic coin">'+COIN+'</span></span>';
    }catch(e){ return ''; }
  };

  /* ---------------------------------------------------------------- EVENTI */
  var EVT=[
    {t:'coin',v:400,   nm:'400 monete'},
    {t:'exp', v:150,   nm:'150 EXP'},
    {t:'pack',v:'bronzo',     nm:'Pacchetto Bronzo'},
    {t:'coin',v:700,   nm:'700 monete'},
    {t:'exp', v:250,   nm:'250 EXP'},
    {t:'coin',v:900,   nm:'900 monete'},
    {t:'pack',v:'bronzoplus', nm:'Bronzo Plus'},
    {t:'exp', v:300,   nm:'300 EXP'},
    {t:'coin',v:1100,  nm:'1.100 monete'},
    {t:'coin',v:1300,  nm:'1.300 monete'},
    {t:'exp', v:400,   nm:'400 EXP'},
    {t:'pack',v:'argento',    nm:'Pacchetto Argento'},
    {t:'coin',v:1500,  nm:'1.500 monete'},
    {t:'exp', v:500,   nm:'500 EXP'},
    {t:'coin',v:1800,  nm:'1.800 monete'},
    {t:'exp', v:600,   nm:'600 EXP'},
    {t:'pack',v:'argento72',  nm:'Argento Raro'},
    {t:'coin',v:2200,  nm:'2.200 monete'},
    {t:'exp', v:800,   nm:'800 EXP'},
    {t:'coin',v:2600,  nm:'2.600 monete'},
    {t:'pack',v:'oro',        nm:'Pacchetto Oro'}
  ];
  var MILES=[3,7,12,17,21];
  window.EVT=EVT;

  function dk(){ try{ return dayKey(); }catch(e){ var d=new Date(); return d.toDateString(); } }
  function est(){
    if(!window.S) return {day:0,last:''};
    if(!S.evt) S.evt={day:0,last:''};
    return S.evt;
  }
  function eready(){ var E=est(); return E.last!==dk() && (E.day|0)<EVT.length; }
  window.evtReady=eready;

  window.evtHTML=function(){
    var E=est(), cur=E.day|0, ready=eready(), cells='', i;
    for(i=0;i<EVT.length;i++){
      var rw=EVT[i], done=(i<cur), now=(ready&&i===cur), mile=(MILES.indexOf(i+1)>=0);
      cells+='<div class="ev3-c'+(done?' done':'')+(now?' now':'')+(mile?' mile':'')+'">'+
        '<div class="a">'+rwArt(rw)+'</div>'+
        '<div class="d">Giorno '+(i+1)+'</div></div>';
    }
    var miles='';
    for(i=0;i<MILES.length;i++){
      var m=MILES[i], on=(cur>=m);
      var mr=EVT[m-1];
      miles+='<div class="ev3-m'+(on?' on':'')+'"><div class="c">'+rwArt(mr)+'</div>'+
        '<div class="d">'+m+'</div></div>';
    }
    var pct=Math.max(0,Math.min(100,Math.round(cur/21*100)));
    return '<div class="kfm-body">'+
      '<div class="ev3-hero"><div><h4>Peak Season Check-in</h4>'+
        '<p>Accedi ogni giorno per 21 giorni. Ogni traguardo sblocca un premio maggiore: '+
        'al giorno 21 ti aspetta il Pacchetto Oro.</p>'+
        '<div class="ev3-bar"><i style="width:'+pct+'%"></i></div></div>'+
        '<div class="ev3-miles">'+miles+'</div></div>'+
      '<div class="ev3-grid">'+cells+'</div>'+
      '<div class="ev3-foot"><div class="tx"><b>Accessi totali: '+cur+' / 21</b>'+
        (ready?'Ricompensa del giorno '+(cur+1)+' disponibile':
          (cur>=EVT.length?'Evento completato':'Gia\u0027 riscosso oggi \u00b7 torna domani'))+'</div>'+
        (ready?'<button class="kfm-cta" data-ac="claimevt">Riscuoti</button>':
               '<div class="kfm-cta off">'+(cur>=EVT.length?'Completato':'Torna domani')+'</div>')+
      '</div></div>';
  };

  window.evtClaim=function(){
    var E=est();
    if(!eready()){ try{ toast('Hai gia\u0027 riscosso il check-in di oggi.'); }catch(e){} return; }
    var rw=EVT[E.day|0], msg='';
    try{
      if(rw.t==='coin'){ S.coins+=rw.v; msg='+'+nfmt(rw.v)+' monete'; }
      else if(rw.t==='exp'){ S.exp+=rw.v; msg='+'+nfmt(rw.v)+' EXP'; }
      else { var p=pk(rw.v); if(p){ var got=openPack(p); msg=rw.nm+': '+got.length+' carte'; } }
    }catch(e){}
    E.day=(E.day|0)+1; E.last=dk();
    try{ toast('<b>Check-in giorno '+E.day+'</b> \u00b7 '+msg); }catch(e){}
    try{ save(); }catch(e){}
    try{ render(); }catch(e){}
  };

  /* ------------------------------------------------------------ OBIETTIVI */
  window.objHTML=function(){
    var list=[];
    try{
      var all=0, k; for(k in S.cards) all++;
      var r=(typeof ratings==='function')?ratings():{n:0,ovr:0};
      var me=null; try{ me=tabRow(S.club); }catch(e){}
      var jn=0; try{ jn=jnTotDone(); }catch(e){}
      list=[
        {n:'Colleziona 25 carte', s:'Collezione', c:all, g:25, rw:{coin:2500,exp:400}},
        {n:'Schiera un undici completo', s:'Formazione', c:r.n||0, g:11, rw:{coin:800,exp:150}},
        {n:'Vinci 5 partite di lega', s:'Competizione', c:(me?me.w:0), g:5, rw:{coin:4000,tok:5}},
        {n:'Squadra da 80 di media', s:'Rosa', c:r.ovr||0, g:80, rw:{coin:9000,tok:12}},
        {n:'Vinci 30 sfide Journey', s:'Journey', c:jn, g:30, rw:{coin:15000,tok:25}}
      ];
    }catch(e){ list=[]; }
    var IC=['<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="16" rx="2.4"/><path d="M8 4v16M16 4v16"/></svg>',
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 3v18M3 12h18"/></svg>',
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M6 4h12v5a6 6 0 0 1-12 0z"/><path d="M6 6H3v2a3 3 0 0 0 3 3M18 6h3v2a3 3 0 0 1-3 3M9 20h6M12 15v5"/></svg>',
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3l2.7 5.7 6.1.9-4.4 4.4 1 6.2L12 17.3 6.6 20.2l1-6.2L3.2 9.6l6.1-.9z"/></svg>',
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="13" r="8"/><path d="M12 9v4l2.6 1.7M9.4 2.4h5.2"/></svg>'];
    var rows='';
    for(var i=0;i<list.length;i++){
      var o=list[i], pct=Math.min(100,Math.round((o.c||0)/o.g*100)), ok=(o.c||0)>=o.g;
      var chips='';
      if(o.rw.coin) chips+='<span class="ob3-chip"><i>'+COIN+'</i>'+nfmt(o.rw.coin)+'</span>';
      if(o.rw.exp)  chips+='<span class="ob3-chip exp"><i>'+EXPIC+'</i>'+nfmt(o.rw.exp)+' EXP</span>';
      if(o.rw.tok)  chips+='<span class="ob3-chip tok">'+o.rw.tok+' token</span>';
      rows+='<div class="ob3-r'+(ok?' ok':'')+'">'+
        '<span class="ob3-ic">'+IC[i%IC.length]+'</span>'+
        '<div><div class="ob3-nm">'+ee(o.n)+'</div>'+
          '<div class="ob3-sub">'+ee(o.s)+' \u00b7 '+Math.min(o.c||0,o.g)+' / '+o.g+(ok?' \u00b7 completato':'')+'</div>'+
          '<div class="ob3-bar"><i style="width:'+pct+'%"></i></div></div>'+
        '<div class="ob3-rw">'+chips+'</div></div>';
    }
    return '<div class="kfm-body"><div class="ob3">'+rows+'</div></div>';
  };
})();
